import { Injectable, NotFoundException } from '@nestjs/common';

export interface NinProfile {
  nin: string;
  firstName: string;
  middleName: string;
  surname: string;
  gender: string;
  dateOfBirth: string;
  phone: string | null;
  email: string;
  photoBase64: string;
}

// Hardcoded mock NIN API response — only NIN 00000000001 is supported.
// This simulates what a paid third-party vendor (e.g. Smile Identity) would return.
const MOCK_NIN_DATABASE: Record<string, NinProfile> = {
  '00000000001': {
    nin: '00000000001',
    firstName: 'TAIWO',
    middleName: 'DANIEL',
    surname: 'AKERELE',
    gender: 'M',
    dateOfBirth: '01-10-1960',
    phone: '09032562302',
    email: 'taiwoakerele98@gmail.com',
    photoBase64:
      '',
  },
};

@Injectable()
export class NinMockService {
  /**
   * Simulates a call to a third-party NIN verification vendor (e.g. Smile Identity).
   * Only NIN 00000000001 is supported in this MVP demo.
   * Returns the profile and the enrolled photo decoded as a Buffer.
   */
  lookup(nin: string): { profile: Omit<NinProfile, 'photoBase64'>; photoBuffer: Buffer } {
    const entry = MOCK_NIN_DATABASE[nin.trim()];
    if (!entry) {
      throw new NotFoundException(
        `NIN ${nin} not found. Only NIN 00000000001 is supported in the demo environment.`,
      );
    }
    const { photoBase64, ...profile } = entry;
    const photoBuffer = Buffer.from(photoBase64, 'base64');
    return { profile, photoBuffer };
  }
}
